cat > instalar-vps.sh <<'INST_EOF'
#!/usr/bin/env bash
# Instala o app CTAF na VPS (Ubuntu). Não apaga nada existente. Uso: bash instalar-vps.sh EMAIL_DO_CLUBE [SUBDOMINIO]
set -euo pipefail
EMAIL="${1:?Informe o e-mail de login do clube. Ex: bash instalar-vps.sh diretoria@ctaf.com.br}"
HOST="${2:-ctaf.atitech.io}"; PORT=3410; DIR=/opt/ctaf; SRC="$(cd "$(dirname "$0")" && pwd)"
[ "$(id -u)" = 0 ] || { echo "Rode como root"; exit 1; }
[ -d "$DIR/app" ] && echo "Atualizando instalação existente em $DIR" || echo "Nova instalação em $DIR"
mkdir -p "$DIR/app" "$DIR/data" "$DIR/browsers"
apt-get update -y -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq ffmpeg python3-venv python3-pip curl ca-certificates >/dev/null
if ! command -v node >/dev/null || [ "$(node -p 'process.versions.node.split(".")[0]')" -lt 20 ]; then
  curl -fsSL https://deb.nodesource.com/setup_22.x | bash - && apt-get install -y -qq nodejs >/dev/null; fi
command -v pm2 >/dev/null || npm i -g pm2 >/dev/null
tar -xzf "$SRC/ctaf-app.tar.gz" -C "$DIR/app"
cd "$DIR/app"
if [ ! -f "$DIR/.env" ]; then
  umask 077
  cat > "$DIR/.env" <<ENV
SESSION_SECRET=$(openssl rand -hex 32)
DATA_DIR=$DIR/data
PLAYWRIGHT_BROWSERS_PATH=$DIR/browsers
REMBG_BIN=$DIR/venv/bin/rembg
COOKIE_SECURE=1
NODE_ENV=production
PORT=$PORT
DAILY_LIMIT=5
ENV
fi
[ -x "$DIR/venv/bin/rembg" ] || { python3 -m venv "$DIR/venv" && "$DIR/venv/bin/pip" install -q "rembg[cli]" onnxruntime; }
npm ci --silent
mkdir -p public/fonts; F=node_modules/@fontsource; cp $F/bebas-neue/files/bebas-neue-latin-400-normal.woff2 public/fonts/bebas.woff2; for w in 400 600 800 900; do cp $F/inter/files/inter-latin-$w-normal.woff2 public/fonts/inter-$w.woff2; done
PLAYWRIGHT_BROWSERS_PATH="$DIR/browsers" npx playwright install --with-deps chromium
npm run build
DATA_DIR="$DIR/data" node scripts/seed.mjs "$EMAIL"
pm2 describe ctaf-app >/dev/null 2>&1 && pm2 delete ctaf-app
pm2 start "node --env-file=$DIR/.env node_modules/next/dist/bin/next.js start -p $PORT" --name ctaf-app --cwd "$DIR/app" >/dev/null || \
pm2 start "node --env-file=$DIR/.env node_modules/next/dist/bin/next start -p $PORT" --name ctaf-app --cwd "$DIR/app"
pm2 save >/dev/null
CF=/etc/caddy/Caddyfile
if [ -f "$CF" ]; then
  grep -q "^$HOST" "$CF" || { cp "$CF" "$CF.bak.$(date +%s)"; printf '\n%s {\n\treverse_proxy localhost:%s\n}\n' "$HOST" "$PORT" >> "$CF"; }
  caddy validate --config "$CF" >/dev/null && systemctl reload caddy
else echo "ATENÇÃO: Caddyfile não encontrado em $CF — aponte $HOST para localhost:$PORT manualmente."; fi
echo; echo "PRONTO: https://$HOST  (login: $EMAIL)"; echo "Senha gerada: leia com   cat $DIR/data/CREDENCIAIS.txt   (apague o arquivo depois de anotar)"
INST_EOF
bash instalar-vps.sh "${1:-diretoria@ctaf.com.br}"
